        var p = ["DECLARE Score : INTEGER", "INPUT Score", "IF Score " + op + " " + t + " THEN", "  OUTPUT \"" + w[0] + "\"", "ELSE", "  OUTPUT \"" + w[1] + "\"", "ENDIF"];
        var ans = out(p, [input]);
        var wt = pick(10, 60, [t]), wop = drillPick([">=", ">"]), win = wt, wl = ["DECLARE Age : INTEGER", "INPUT Age", "IF Age " + wop + " " + wt + " THEN", "  OUTPUT \"Allowed\"", "ELSE", "  OUTPUT \"Too young\"", "ENDIF"];
