          step("Pass 3: Count = 3. Total = " + (ws - 3) + " - 3 = " + (ws - 6) + ". Count reached 3, so the loop ends.", wl, [3, 4], "Count  Total\n  3     " + (ws - 6)),
          step("Last row: OUTPUT shows " + (ws - 6) + ", once, after the loop.", wl, 6, "OUTPUT: " + (ws - 6))
