    // ================================================================ WHILE loops
    // Number goes down until the condition fails (6 of 13 ran it once in the test).
    function whileWalk(s, lim, d) {
      var wl = ["DECLARE Number : INTEGER", "Number <- " + s, "WHILE Number > " + lim + " DO", "  Number <- Number - " + d, "ENDWHILE", "OUTPUT Number"];
      var steps = [step("A similar program. A WHILE loop asks its question BEFORE every pass, again and again, until the answer is No. It is not an IF: it can run many times.", wl, 2), step("Number starts at " + s + ".", wl, 1, "Number = " + s)];
      var n = s, guard = 0;
      while (n > lim && guard++ < 20) {
        steps.push(step("Check: is " + n + " > " + lim + "? Yes, so run the loop: " + n + " - " + d + " = " + (n - d) + ". Then go back to the WHILE line.", wl, [2, 3], "Number = " + (n - d)));
        n -= d;
      }
      steps.push(step("Check: is " + n + " > " + lim + "? No. The loop stops here and the program moves past ENDWHILE.", wl, 2, "Number = " + n));
      steps.push(step("OUTPUT shows " + n + ", the value when the check first said No.", wl, 5, "OUTPUT: " + n));
      check(out(wl) === String(n), "while walk");
      return steps;
    }
